import numpy as np

# For each gap, check if it can reach the border in one direction (above, below, left, or right)
def can_reach_border(grid, bg, frame, r, c, direction):
    """Check if background at (r,c) can reach border without passing through frame."""
    if direction == 'up':
        rr, rc = r - 1, c
        while rr >= 0:
            if grid[rr][rc] == frame:
                return False
            if rr in [0, len(grid) - 1]:
                return True
            rr -= 1
        return False
    elif direction == 'down':
        rr, rc = r + 1, c
        while rr < len(grid):
            if grid[rr][rc] == frame:
                return False
            if rr in [0, len(grid) - 1]:
                return True
            rr += 1
        return False
    elif direction == 'left':
        rr, rc = r, c - 1
        while rc >= 0:
            if grid[rr][rc] == frame:
                return False
            if rc in [0, len(grid[0]) - 1]:
                return True
            rc -= 1
        return False
    elif direction == 'right':
        rr, rc = r, c + 1
        while rc < len(grid[0]):
            if grid[rr][rc] == frame:
                return False
            if rc in [0, len(grid[0]) - 1]:
                return True
            rc += 1
        return False
    return False

def gap_changes(grid, bg, frame, r, c):
    """A gap changes if it can reach the border in at least one direction."""
    up = can_reach_border(grid, bg, frame, r, c, 'up')
    down = can_reach_border(grid, bg, frame, r, c, 'down')
    left = can_reach_border(grid, bg, frame, r, c, 'left')
    right = can_reach_border(grid, bg, frame, r, c, 'right')
    return (up or down or left or right), (up, down, left, right)

