import numpy as np

def is_horizontal_frame_tunnel(grid, bg, frame, r, c):
    """Check if (r,c) is a background cell in a horizontal tunnel (frame left and right)."""
    if grid[r][c] != bg:
        return False
    # Check if left and right are frame
    left = grid[r][c-1] if c > 0 else None
    right = grid[r][c+1] if c+1 < len(grid[0]) else None
    if left != frame or right != frame:
        return False
    return True

def is_vertical_frame_tunnel(grid, bg, frame, r, c):
    """Check if (r,c) is a background cell in a vertical tunnel (frame above and below)."""
    if grid[r][c] != bg:
        return False
    # Check if above and below are frame
    above = grid[r-1][c] if r > 0 else None
    below = grid[r+1][c] if r+1 < len(grid) else None
    if above != frame or below != frame:
        return False
    return True

# Now let's check a stronger condition:
# For a horizontal tunnel to be "complete", the ENTIRE segment of background cells
# between frame must be bounded by frame on top and bottom.
# For a horizontal gap at (r,c), check all bg cells in the same row between frame cells.
def horizontal_tunnel_complete(grid, bg, frame, r, c):
    """A horizontal tunnel is complete if all bg cells between frame cells have frame above AND below."""
    if not is_horizontal_frame_tunnel(grid, bg, frame, r, c):
        return False
    # Find all consecutive bg cells starting from (r,c) going left toward the left frame
    start_c = c
    while start_c > 0 and grid[r][start_c] == frame:
        start_c -= 1
    end_c = start_c + 1
    while end_c < len(grid[0]) and grid[r][end_c] != frame:
        end_c += 1
    # Now all cells from (r, start_c+1) to (r, end_c-1) are bg and have frame on both sides
    # Check if all have frame above and below
    for cc in range(start_c + 1, end_c):
        if grid[r-1][cc] != frame or grid[r+1][cc] != frame:
            return False
    return True

def vertical_tunnel_complete(grid, bg, frame, r, c):
    """A vertical tunnel is complete if all bg cells between frame cells have frame left AND right."""
    if not is_vertical_frame_tunnel(grid, bg, frame, r, c):
        return False
    # Find all consecutive bg cells starting from (r,c) going up toward the top frame
    start_r = r
    while start_r > 0 and grid[start_r][c] == frame:
        start_r -= 1
    end_r = start_r + 1
    while end_r < len(grid) and grid[end_r][c] != frame:
        end_r += 1
    # Now all cells from (start_r+1, c) to (end_r-1, c) are bg and have frame above and below
    # Check if all have frame left and right
    for rr in range(start_r + 1, end_r):
        if grid[rr][c-1] != frame or grid[rr][c+1] != frame:
            return False
    return True

